long long countPaths(int m, int n, vector<vector<int>>& bl) {
    const long long M = 1e9 + 7; int N = m + n; auto pw = [&](long long b, long long e) { long long r = 1; b %= M; while (e) { if (e & 1) r = r * b % M; b = b * b % M; e >>= 1; } return r; };
    vector<long long> f(N + 1, 1), inv(N + 1, 1); for (int i = 1; i <= N; i++) f[i] = f[i-1] * i % M; inv[N] = pw(f[N], M - 2); for (int i = N; i > 0; i--) inv[i-1] = inv[i] * i % M;
    auto C = [&](int a, int b) -> long long { return b < 0 || b > a ? 0 : f[a] * inv[b] % M * inv[a-b] % M; };
    vector<pair<int,int>> p; for (auto& b : bl) p.push_back({b[0], b[1]}); sort(p.begin(), p.end()); p.push_back({m - 1, n - 1});
    vector<long long> w(p.size()); for (size_t i = 0; i < p.size(); i++) { long long x = C(p[i].first + p[i].second, p[i].first); for (size_t j = 0; j < i; j++) if (p[j].first <= p[i].first && p[j].second <= p[i].second) x = (x - w[j] * C(p[i].first - p[j].first + p[i].second - p[j].second, p[i].first - p[j].first) % M + M) % M; w[i] = x; }
    return w.back();
}
